"""Bank table construction, exact-key entry counting and runtime matching.

A range bank needs one entry per kept cluster.  An exact bank has separate
tables per pattern length; each pattern denotes its Cartesian product of
integer interval values excluding 1514 at every coordinate.  Identical exact
keys of the same length occupy one entry (their action is the highest-priority
matching cluster); keys of different lengths are distinct.
"""
PAD = 1514
BASE = 3029
ENUM_LIMIT = 6000000


def range_entry_count(kept):
    return len(kept)


def _coord_sets(interval):
    """Allowed value set of [lo,hi] excluding 1514, as sorted (a,b) tuples."""
    lo, hi = interval
    if lo <= PAD <= hi:
        parts = []
        if lo <= PAD-1:
            parts.append((lo, PAD-1))
        if PAD+1 <= hi:
            parts.append((PAD+1, hi))
        return parts
    return [(lo, hi)]


def _canonical(pattern):
    sets = tuple(_coord_sets(iv) for iv in pattern)
    for part in sets:
        if not part:
            return None
    return sets


def _volume(sets):
    v = 1
    for part in sets:
        total = 0
        for a, b in part:
            total += b - a + 1
        v *= total
        if v >= 1 << 60:
            return v
    return v


def _powers(L):
    p = [1]
    for _ in range(L-1):
        p.append(p[-1]*BASE)
    return p  # p[j] = BASE^(L-1-j)


def _sub_intervals(sets):
    """Decompose a canonical box into disjoint ascending integer intervals."""
    L = len(sets)
    pw = _powers(L)
    out = [(0, 0)]
    for j in range(L):
        nxt = []
        for lo, hi in out:
            for a, b in sets[j]:
                nxt.append((lo + a*pw[j], hi + b*pw[j]))
        out = nxt
    out.sort()
    return out


def _merge(covered, subs):
    """Union of two sorted disjoint interval lists -> sorted disjoint list."""
    merged = []
    i = j = 0
    while i < len(covered) or j < len(subs):
        if j >= len(subs) or (i < len(covered) and covered[i][0] < subs[j][0]):
            item = covered[i]; i += 1
        else:
            item = subs[j]; j += 1
        if merged and item[0] <= merged[-1][1] + 1:
            if item[1] > merged[-1][1]:
                merged[-1][1] = item[1]
        else:
            merged.append([item[0], item[1]])
    return merged


def _union_count(boxes, kcap):
    """min(number of distinct keys of the boxes, kcap)."""
    if kcap <= 0:
        return 0
    volumes = [_volume(b) for b in boxes]
    for v in volumes:
        if v >= kcap:
            return kcap
    order = sorted(range(len(boxes)), key=lambda i: -volumes[i])
    if sum(volumes) <= ENUM_LIMIT:
        seen = set()
        for i in order:
            for a, b in _sub_intervals(boxes[i]):
                for key in range(a, b+1):
                    seen.add(key)
                    if len(seen) >= kcap:
                        return kcap
        return len(seen)
    covered = []
    total = 0
    for i in order:
        subs = _sub_intervals(boxes[i])
        overlap = 0
        k = 0
        for a, b in subs:
            while k < len(covered) and covered[k][1] < a:
                k += 1
            m = k
            while m < len(covered) and covered[m][0] <= b:
                lo = a if a > covered[m][0] else covered[m][0]
                hi = b if b < covered[m][1] else covered[m][1]
                if hi >= lo:
                    overlap += hi - lo + 1
                m += 1
        new = volumes[i] - overlap
        if new > 0:
            total += new
            if total >= kcap:
                return kcap
            covered = _merge(covered, subs)
    return total


def exact_entry_count(patterns, cap_exact):
    """min(actual distinct keys, capacity.exact+1) across pattern lengths."""
    K = cap_exact + 1
    by_len = {}
    for pattern in patterns:
        by_len.setdefault(len(pattern), []).append(pattern)
    total = 0
    for L in sorted(by_len):
        seen = {}
        for pattern in by_len[L]:
            box = _canonical(pattern)
            if box is not None:
                seen[box] = None
        if seen:
            total += _union_count(list(seen), K - total)
            if total >= K:
                return K
    return total


class Matcher:
    """Highest-priority kept-cluster matching on sliding suffix windows."""

    def __init__(self, kept):
        """kept: [(cluster_id, class, range pattern)] in priority order."""
        by_len = {}
        for rank, (cid, cls, pattern) in enumerate(kept):
            by_len.setdefault(len(pattern), []).append((rank, cid, cls, pattern))
        self.groups = []
        for L, plist in by_len.items():
            plist.sort(key=lambda t: t[0])
            dicts = []
            for j in range(L):
                adds = {}
                rems = {}
                for i, (_, _, _, pattern) in enumerate(plist):
                    lo, hi = pattern[j]
                    adds.setdefault(lo, []).append(i)
                    rems.setdefault(hi+1, []).append(i)
                table = {}
                mask = 0
                for v in range(0, PAD*2):
                    for i in adds.get(v, ()):
                        mask |= 1 << i
                    for i in rems.get(v, ()):
                        mask ^= 1 << i
                    if mask:
                        table[v] = mask
                dicts.append(table)
            self.groups.append((L, plist, dicts))
        self.groups.sort(key=lambda g: g[1][0][0])

    def best(self, features, consumed):
        """(rank, cluster_id, class, length) of the highest-priority match
        of any suffix window ending at the last consumed packet, else None."""
        best = None
        for L, plist, dicts in self.groups:
            if L > consumed:
                continue
            if best is not None and plist[0][0] > best[0]:
                break
            mask = (1 << len(plist)) - 1
            base = consumed - L
            for j in range(L):
                mask &= dicts[j].get(features[base+j], 0)
                if not mask:
                    break
            if mask:
                i = (mask & -mask).bit_length() - 1
                rank, cid, cls, _ = plist[i]
                if best is None or rank < best[0]:
                    best = (rank, cid, cls, L)
        return best
